start

:RTOS State Machine Execution;

partition "Temperature Management (High-Priority Task)" {
    :Wait for Ambient Temperature Threshold Breach;

    fork
        :Activate Temperature Adjustment Module;
    fork again
        :Enable Fan Cooling (PWM);
    end fork

    :Monitor Temperature Rise;

    repeat :Execute Rapid Cooling Subroutine;
        note right: Controlled loop with\nexponential backoff
    repeat while (Temperature in safe range?) is (No)
    -> Yes;

    :Disable Fan Cooling;
    :Halt Temperature Adjustment Module;
}

partition "Humidity Management (High-Priority Task)" {
    :Wait for Humidity Alert;

    fork
        :Initialize Humidity Monitor;
    fork again
        :Activate Dehumidifier;
    end fork

    :Wait for Humidity Normalization;

    :Stop Humidity Monitor;
    :Stop Dehumidifier;
}

partition "Telemetry & Sensor Management" {
    repeat :Telemetry Monitor (Timer ISR);
        note right: Periodic loop
        :Bounded Retries & Watchdog Fault Recovery;
    repeat while (Continue periodic loop?) is (Yes)
    -> No;

    repeat :Sensor Fusion & Calibration Routines;
        note right: Execute periodically
        if (Out-of-range readings detected?) then (Yes)
            :Trigger Sensor Redundancy;
            :Initiate Controlled Cool-down Safety State (FADEC);
        else (No)
        endif
    repeat while (Continue periodic routines?) is (Yes)
    -> No;
}

:Return to Low-Power Standby Mode;

stop
